# Recorded self-critique revision: strengthen the measurable geometry page and native diagrams.
def setbody(index,body):
 name,c=pages[index];head=c.split('<div class="content">',1)[0];tail=c.rsplit('</div><div class="note">',1)[1];pages[index]=(name,head+'<div class="content">'+body+'</div><div class="note">'+tail)
svg=f'<svg width="790" height="510" viewBox="0 0 790 510" role="img" aria-label="Measured V edge construction"><rect width="790" height="510" fill="{W}"/><line x1="440" y1="70" x2="311" y2="440" stroke="{N}" stroke-width="36"/><line x1="440" y1="70" x2="440" y2="440" stroke="{N}" stroke-width="3" stroke-dasharray="10 10"/><line x1="311" y1="440" x2="440" y2="440" stroke="{O}" stroke-width="12"/><text x="480" y="250" fill="{N}" font-family="Cairo" font-size="44">h</text><text x="330" y="485" fill="{N}" font-family="Cairo" font-size="32">Δx = h × 0.3494</text><text x="60" y="100" fill="{N}" font-family="Cairo" font-size="42">19.26°</text></svg>'
setbody(14,'<div class="grid"><div>'+svg+'</div><div>'+para('One measured edge creates the boundary. The orange span marks the decision, not a new logo.','en')+para(f'Slope {slope:.4f} px/px; lean {angle:.2f}° from vertical. Use Δx = h × {abs(slope):.4f} at every size.','en')+para('Keep the cut clear of type and original mark. A diagram is explanation, never proof of a project.','en')+'</div></div>')

# A real construction grid: 12 columns, gutters, anchored content and reading direction.
cols=''.join(f'<rect x="{96+i*124}" y="70" width="100" height="400" fill="{T}"/>' for i in range(12))
grid=f'<svg width="1728" height="560" viewBox="0 0 1728 560" role="img" aria-label="12-column layout construction"><rect width="1728" height="560" fill="{W}"/>{cols}<path d="M350 90H750L620 465H220Z" fill="{N}"/><rect x="875" y="125" width="635" height="95" fill="{N}"/><rect x="1000" y="255" width="510" height="22" fill="{N}"/><rect x="1120" y="305" width="390" height="22" fill="{N}"/><path d="M945 370L910 470H875L910 370Z" fill="{O}"/><text x="950" y="525" fill="{N}" font-family="Cairo" font-size="32">AR FIRST / 01 → DECISION → EVIDENCE</text><text x="90" y="42" fill="{N}" font-family="Cairo" font-size="30">12 COLUMNS / 24 px GUTTER / 96 px PAGE MARGIN</text></svg>'
setbody(13,grid)

# Rebuild native applications with distinct educational content at measured slope.
kitchen=f'<svg width="936" height="470" viewBox="0 0 936 470" role="img" aria-label="Concept kitchen clearance"><path d="M210 40H860V140H400V410H210Z" fill="none" stroke="{W}" stroke-width="7"/><path d="M520 330H850" stroke="{W}" stroke-width="7"/><path d="M100 425L230 50" stroke="{W}" stroke-width="6"/><path d="M420 370Q620 230 810 235" fill="none" stroke="{O}" stroke-width="14" stroke-dasharray="18 18"/><text x="510" y="430" fill="{W}" font-family="Cairo" font-size="36">CONCEPT / CLEAR PATH</text></svg>'
drawer=f'<svg width="936" height="480" viewBox="0 0 936 480" role="img" aria-label="Concept drawer clearance"><path d="M160 70H830V250H160Z" fill="none" stroke="{W}" stroke-width="7"/><path d="M220 250H770L710 420H160Z" fill="none" stroke="{W}" stroke-width="7"/><path d="M415 235H443L415 315H387Z" fill="{O}"/><circle cx="415" cy="320" r="22" fill="{O}"/><text x="530" y="380" fill="{W}" font-family="Cairo" font-size="34">CONCEPT / OPENING</text></svg>'
for name,visual in [('kitchen-ad',kitchen),('carousel-cover',drawer),('story-cover',drawer)]:
 body,cl=apps[name]
 start=body.index('<div class="schema">');end=body.index('</div>',start)+6
 body=body[:start]+f'<div style="margin-top:50px">{visual}</div>'+body[end:]
 if name=='story-cover':body=body.replace('<svg width="936" height="480"','<svg style="margin-top:0px" width="936" height="650"')
 text=f'<!doctype html><html><meta charset="utf-8"><style>{app_css}</style><main class="{cl}">{lg()}{body}<div class="disclosure">CONCEPT / EDUCATIONAL DIAGRAM - CHANNEL TBC</div></main></html>'
 (g/'sources'/f'app-{name}.html').write_text(text,encoding='utf-8',newline='\n')


webcss=f'@font-face{{font-family:Cairo;src:url("../../assets/fonts/cairo.ttf");font-weight:200 1000}}*{{box-sizing:border-box}}body{{margin:0;background:{W};color:{N};font-family:Cairo}}header{{padding:24px 64px;background:{N};height:200px}}header img{{width:190px;height:190px;object-fit:contain;margin-top:-20px}}section{{padding:48px 64px;display:grid;grid-template-columns:1fr 1fr;gap:48px}}h1{{font-size:56px;line-height:1.35;font-weight:900;margin:0 0 20px;text-align:right;direction:rtl}}p{{font-size:18px;line-height:1.6}}.cta{{display:inline-block;background:{O};color:{N};padding:16px 24px;font-weight:800;direction:rtl}}.visual{{background:{N};padding:20px}}.visual svg{{width:100%;height:auto}}.label{{font-size:16px;background:{N};color:{W};padding:16px 64px}}@media(max-width:700px){{header{{padding:16px 24px;height:160px}}header img{{width:155px;height:155px}}section{{padding:28px 24px;display:flex;flex-direction:column;gap:32px}}h1{{font-size:36px}}.label{{padding:16px 24px}}}}'
webbody=f'<header>{lg()}</header><section><div><h1>مطبخ مش في طريقك.</h1><p>A kitchen that stays out of your way.</p><div class="cta">ابدأ مراجعة مطبخك.</div><p>Start your kitchen review.</p><p>CONCEPT / DRAFT LENS COPY / CHANNEL TBC</p></div><div class="visual">{kitchen}</div></section><div class="label">EDUCATIONAL DIAGRAM - NOT PROJECT PROOF / RESPONSIVE SPECIMEN</div>'
(g/'sources/responsive-web.html').write_text(f'<!doctype html><html><meta charset="utf-8"><style>{webcss}</style>{webbody}</html>',encoding='utf-8',newline='\n')

